# Generates CycleClasses.h/.cpp + targets_cycle.txt for the six SetCycleProp* subclasses.
use strict;
chdir "../../.." or die;
my $exe = do { local $/; open my $f, "<:raw", "Exported/SQZ.EXE" or die; <$f> };
sub rva2off { my ($va) = @_; my $pe = unpack('V', substr($exe,0x3c,4)); my ($nsec,$opt) = unpack('x6 v x12 v', substr($exe,$pe,24)); my $base = unpack('V', substr($exe,$pe+24+28,4));
  for my $i (0..$nsec-1) { my ($vs,$va0,$rs,$rp) = unpack('x8 V V V V', substr($exe,$pe+24+$opt+$i*40,40)); my $r = $va-$base; return $rp+$r-$va0 if $r >= $va0 && $r < $va0+$vs; } die }
sub cstr { return unpack('Z*', substr($exe, rva2off($_[0]), 64)); }
sub bytes { return substr($exe, rva2off($_[0]), $_[1]); }
my %fsz; { open my $ff, "<nm/fns_all.txt" or die; while (<$ff>) { $fsz{hex($1)} = $2 if /^([0-9a-f]+) size=(\d+)/ } }
sub sddsize { my ($a) = @_; my $n = $fsz{$a} // 104; my $b = bytes($a, $n + 64); my $best = 0;
  for my $i (0..$n-5) { next unless substr($b,$i,1) eq "\xe8"; my $t = $a + $i + 5 + unpack('l', substr($b,$i+1,4)); my $s = $t + 8 - $a; $best = $s if $t > $a + $n - 8 && $t < $a + $n + 40 && $s > $best; }
  return $best || $n; }
my %apply = (
  PathTime  => ['PathProp', 'SetTime', 'float', 'prop->SetTime(value->Get(extra));', 0],
  PathWrap  => ['PathProp', 'SetWrap', 'int',   'prop->SetWrap((int)value->Get(extra));', 0],
  PathDir   => ['PathProp', 'SetDir',  'int',   'prop->SetDir((int)value->Get(extra));', 0],
  Frame     => ['FrameProp', 'SetFrame', 'int', 'prop->SetFrame((int)value->Get(extra));', 1],
  FrameWrap => ['FrameProp', 'SetFrameWrap', 'int', 'prop->SetFrameWrap((int)value->Get(extra));', 1],
  FrameDir  => ['FrameProp', 'SetFrameDir', 'int', 'prop->SetFrameDir((int)value->Get(extra));', 1],
);
my $q = '^' . chr(92) . '?'; my $bs = chr(92);
open R, "<tools/rtti.tsv"; my (@h, @c, @t);
while (<R>) { chomp; my @f = split /\t/; next unless $f[0] =~ /^\.\?AVSetCycleProp(\w+)Function\@\@$/; my $short = $1; next unless $apply{$short}; my @s = map { hex } split /;/, $f[4];
  my ($sdd, $exec, $create, $print, $name, $app, $make) = @s; my $n = "SetCycleProp${short}Function";
  my $nb = bytes($name, 6); my $str = cstr(unpack('V', substr($nb,1,4)));
  my ($ptype, $meth, $argt, $body, $cast) = @{$apply{$short}};
  push @h, "class $n : public SetCyclePropFunction {\npublic:\n" . ($short eq "FrameWrap" ? "    ~$n() {}\n" : "") . "    virtual const char *Name();\n    virtual int Apply(CycleProp *p, ScriptCall *args, int extra);\n    virtual SetCyclePropFunction *Make();\n};\n";
  my $cb = $cast ? "    FrameProp *prop = (FrameProp *)SqzRTDynamicCast(p, 0, kCyclePropType, kFrameType, 0);\n" : "    PathProp *prop = (PathProp *)p;\n";
  push @c, "const char *$n\::Name() { return \"$str\"; }\nSetCyclePropFunction *$n\::Make() { return new $n; }\nint $n\::Apply(CycleProp *p, ScriptCall *args, int extra)\n{\n$cb    $body\n    return 1;\n}\n";
  my $esz = $fsz{$app} // 48;
  push @t, $q . "Name\@$n  " . sprintf("%x", $name) . " ${short}_name 6\n" . $q . "Make\@$n  " . sprintf("%x", $make) . " ${short}_make " . (($sdd > $make && $sdd - $make < 300) ? ($sdd - $make) : "") . "\n" . $q . "Apply\@$n  " . sprintf("%x", $app) . " ${short}_apply\n" . $q . $bs . "?_G$n  " . sprintf("%x", $sdd) . " ${short}_sdd " . sddsize($sdd) . "\n";
}
open H, ">Repo/src/FunctionCycle/CycleClasses.h"; print H "// The SetCycleProp* subclasses (generated by gen.pl).\n#pragma once\n#include \"FunctionCycle/Cycle.h\"\n\nstruct PathProp {\n    virtual void v0(); virtual void v1(); virtual void v2(); virtual void v3(); virtual void v4(); virtual void v5(); virtual void v6(); virtual void v7();\n    virtual void v8(); virtual void v9(); virtual void v10(); virtual void v11(); virtual void v12(); virtual void v13(); virtual void v14();\n    virtual void SetTime(float);   // slot 15\n    virtual void SetDir(int);      // slot 16\n    virtual void SetWrap(int);     // slot 17\n};\nstruct FrameProp {\n    virtual void v0(); virtual void v1(); virtual void v2(); virtual void v3(); virtual void v4(); virtual void v5(); virtual void v6(); virtual void v7();\n    virtual void v8(); virtual void v9(); virtual void v10(); virtual void v11(); virtual void v12(); virtual void v13(); virtual void v14(); virtual void v15();\n    virtual void v16(); virtual void v17(); virtual void v18(); virtual void v19(); virtual void v20(); virtual void v21();\n    virtual void SetFrame(int);      // slot 22\n    virtual void SetFrameDir(int);   // slot 23\n    virtual void SetFrameWrap(int);  // slot 24\n};\nextern const char kFrameType[];   // 0x4bbb40\n\n", join("\n", @h); close H;
open C, ">Repo/src/FunctionCycle/CycleClasses.cpp"; print C "// Small slots of the SetCycleProp* subclasses (generated by gen.pl).\n#include \"FunctionCycle/CycleClasses.h\"\n\n", join("\n", @c); close C;
open T, ">Repo/src/FunctionCycle/targets_cycle.txt"; print T @t; close T; print scalar(@h), " classes\n";
